// A locked throwing lane has two separate hit windows: outward and returning blade.
const sandBanditSheet=new Image();sandBanditSheet.assetSrc='assets/desert-bandit-v1.png';
function beginSandBandit(e){let angle=Math.atan2(p.y-e.y,p.x-e.x),c=Math.cos(angle),s=Math.sin(angle),reach=0,origin={x:e.x,y:e.y};for(let d=10;d<=280;d+=10){let end={x:e.x+c*d,y:e.y+s*d};if(!lineClear(origin,end,4))break;reach=d;}if(reach<30)return false;e.state='attack';e.elapsed=0;e.struck=false;e.facing=c-s<0?-1:1;e.attack={pattern:'sandReturnBlade',bespoke:true,windup:.8,origin,angle,reach,hits:[false,false],blocked:false};return true;}
function sandBanditPoint(a,d){return{x:a.origin.x+Math.cos(a.angle)*d,y:a.origin.y+Math.sin(a.angle)*d};}
function sandBanditSegmentContains(from,to,point){let dx=to.x-from.x,dy=to.y-from.y,len=dx*dx+dy*dy,t=len?clamp(((point.x-from.x)*dx+(point.y-from.y)*dy)/len,0,1):0;return Math.hypot(point.x-from.x-dx*t,point.y-from.y-dy*t)<=24+1e-8;}
function sweepSandBandit(a,phase,from,to){let length=Math.abs(to-from),steps=Math.max(1,Math.ceil(length/8)),prior=sandBanditPoint(a,from);for(let i=1;i<=steps;i++){let next=sandBanditPoint(a,from+(to-from)*i/steps);if(!lineClear(prior,next,4)){a.blocked=true;return;}if(!a.hits[phase]&&sandBanditSegmentContains(prior,next,p)&&lineClear(a.origin,p)){a.hits[phase]=true;hurt(42);}prior=next;}}
const sandBanditAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{if(e.species!=='r4e2')return sandBanditAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='sandReturnBlade'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=300&&clear&&beginSandBandit(e)){}else{e.state='idle';if(distance>750&&!e.aware)return;if(distance<=180&&clear)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,100*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 let previous=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;let a=e.attack;if(previous<.8&&e.elapsed>=.8)playSound('slash',e.x,e.y);for(let phase=0;phase<2&&!a.blocked;phase++){let start=.8+phase*.7,end=start+.7;if(e.elapsed<start||previous>=end)continue;let from=clamp((previous-start)/.7,0,1),to=clamp((e.elapsed-start)/.7,0,1);sweepSandBandit(a,phase,(phase?1-from:from)*a.reach,(phase?1-to:to)*a.reach);}e.struck=a.hits.some(Boolean);if(e.elapsed>=2.65){e.attack=null;e.state='idle';e.t=2.1;}
};
const sandBanditDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r4e2'||!sandBanditSheet.complete||!sandBanditSheet.naturalWidth||!sandBanditSheet.naturalHeight)return sandBanditDrawBase(e,size);let f=spriteFrame(e.hp<=0?'idle':e.state,e.hp<=0?0:e.anim);if(e.hp>0&&e.attack?.pattern==='sandReturnBlade')f={row:2,col:e.elapsed<.8?0:e.elapsed<1.1?1:e.elapsed<2.2?2:3};let q=project(e.x,e.y),sw=sandBanditSheet.naturalWidth/4,sh=sandBanditSheet.naturalHeight/3,w=120,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,sandBanditSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.96,w,h);else ctx.drawImage(sandBanditSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.96,w,h);ctx.restore();return true;};
const sandBanditSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r4e2'?92:sandBanditSizeBase(e);
const sandBanditGroundBase=drawGroundEffects;drawGroundEffects=()=>{sandBanditGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r4e2'):enemies)){let a=e.attack;if(e.species!=='r4e2'||e.hp<=0||a?.pattern!=='sandReturnBlade'||a.blocked||e.elapsed>=2.2||!visibleAt(e.x,e.y))continue;let end=sandBanditPoint(a,a.reach),c=Math.cos(a.angle),s=Math.sin(a.angle);ctx.save();ctx.strokeStyle=e.elapsed<.8?'#e6b76d':'#f8e8b8';ctx.fillStyle='#dba35720';ctx.lineWidth=1;ctx.beginPath();for(let [i,[along,side]]of [[0,-24],[a.reach,-24],[a.reach,24],[0,24]].entries()){let q=project(a.origin.x+c*along-s*side,a.origin.y+s*along+c*side);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();groundRing(a.origin.x,a.origin.y,24,'#e6b76d',1);groundRing(end.x,end.y,24,'#e6b76d',1);if(e.elapsed>=.8){let t=e.elapsed<1.5?(e.elapsed-.8)/.7:(2.2-e.elapsed)/.7,pos=sandBanditPoint(a,clamp(t,0,1)*a.reach),q=project(pos.x,pos.y);ctx.save();ctx.translate(q.x,q.y-18);ctx.rotate(e.elapsed*24);ctx.strokeStyle='#ffe5a4';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,14,.2,Math.PI*1.55);ctx.stroke();ctx.restore();}}};
